// Evidence-backed request-path tests for the Membership leaf (Phase 3.1).
//
// Generated by scripts/research/gen-31-tests.py from the rows in api.md, which in turn come from
// docs/research/apk-endpoints.md. Each test calls the method and inspects the URL that actually
// reaches `fetch`, so a rename or a route regression fails here rather than in production.

import BandlabSDK from 'bandlab-sdk';

function makeClient(): BandlabSDK {
  return new BandlabSDK({ bearerToken: 'My Bearer Token', baseURL: 'http://127.0.0.1:4010' });
}

/** Run `fn`, capture the URL of the first request, and answer it with a stub response. */
async function captureURL(fn: (c: BandlabSDK) => Promise<unknown>): Promise<string> {
  const calls: string[] = [];
  const realFetch = globalThis.fetch;
  globalThis.fetch = (async (input: any) => {
    calls.push(typeof input === 'string' ? input : input?.url ?? String(input));
    return new Response('{}', { status: 200, headers: { 'content-type': 'application/json' } });
  }) as typeof fetch;
  try {
    await fn(makeClient()).catch(() => undefined);
  } finally {
    globalThis.fetch = realFetch;
  }
  if (!calls.length) throw new Error('no request was issued');
  return calls[0]!;
}

describe('Membership paths match the APK evidence', () => {
  test('GET /coins/users/{userID}/ai-tokens/balance hits /coins/users/{userID}/ai-tokens/balance', async () => {
    const url = await captureURL((c) =>
      c.membership.retrieveCoinsTokenBalance('182bd5e5-6e1a-4fe4-a799-aa6d9a6ab26e'),
    );
    expect(url).toContain('/coins/users/182bd5e5-6e1a-4fe4-a799-aa6d9a6ab26e/ai-tokens/balance');
  });

  test('GET /experiment/users/{userID}/membership-status hits /experiment/users/{userID}/membership-status', async () => {
    const url = await captureURL((c) => c.membership.retrieveStatus('182bd5e5-6e1a-4fe4-a799-aa6d9a6ab26e'));
    expect(url).toContain('/experiment/users/182bd5e5-6e1a-4fe4-a799-aa6d9a6ab26e/membership-status');
  });

  test('GET /membership/surveys/{surveyID} hits /membership/surveys/{surveyID}', async () => {
    const url = await captureURL((c) => c.membership.retrieveSurvey('182bd5e5-6e1a-4fe4-a799-aa6d9a6ab26e'));
    expect(url).toContain('/membership/surveys/182bd5e5-6e1a-4fe4-a799-aa6d9a6ab26e');
  });

  test('POST /membership/surveys/{surveyID}/answers hits /membership/surveys/{surveyID}/answers', async () => {
    const url = await captureURL((c) =>
      c.membership.submitSurveyAnswers('182bd5e5-6e1a-4fe4-a799-aa6d9a6ab26e', {}),
    );
    expect(url).toContain('/membership/surveys/182bd5e5-6e1a-4fe4-a799-aa6d9a6ab26e/answers');
  });

  test('GET /users/{userID}/membership-plan hits /users/{userID}/membership-plan', async () => {
    const url = await captureURL((c) => c.membership.retrievePlan('182bd5e5-6e1a-4fe4-a799-aa6d9a6ab26e'));
    expect(url).toContain('/users/182bd5e5-6e1a-4fe4-a799-aa6d9a6ab26e/membership-plan');
  });

  test('GET /wallet/users/{userID}/balances/ai-tokens hits /wallet/users/{userID}/balances/ai-tokens', async () => {
    const url = await captureURL((c) =>
      c.membership.retrieveWalletTokenBalance('182bd5e5-6e1a-4fe4-a799-aa6d9a6ab26e'),
    );
    expect(url).toContain('/wallet/users/182bd5e5-6e1a-4fe4-a799-aa6d9a6ab26e/balances/ai-tokens');
  });
});
